import subprocess,json,datetime,hashlib
r=Path('E:/OpenLeague');out=r/'tools/hardware/shared_fls';out.mkdir(parents=True,exist_ok=True)
code=r'''use std::{ffi::c_void,sync::{Mutex,mpsc},thread};
static EVENTS:Mutex<Vec<(usize,u32)>>=Mutex::new(Vec::new());
#[link(name="kernel32")]extern "system"{fn FlsAlloc(callback:Option<unsafe extern "system" fn(*mut c_void)>)->u32;fn FlsSetValue(slot:u32,value:*mut c_void)->i32;fn FlsGetValue(slot:u32)->*mut c_void;fn FlsFree(slot:u32)->i32;fn GetCurrentThreadId()->u32;fn GetLastError()->u32;}
unsafe extern "system" fn callback(value:*mut c_void){let _=std::panic::catch_unwind(||{EVENTS.lock().unwrap().push((value as usize,unsafe{GetCurrentThreadId()}));});}
fn main(){for early in[false,true]{EVENTS.lock().unwrap().clear();let owner=unsafe{GetCurrentThreadId()};let slot=unsafe{FlsAlloc(Some(callback))};assert_ne!(slot,u32::MAX);let mut workers=vec![];let mut stops=vec![];let mut ids=vec![];
 for value in[101usize,202]{let(tx,rx)=mpsc::channel();let(stop_tx,stop_rx)=mpsc::channel();workers.push(thread::spawn(move||{assert_ne!(unsafe{FlsSetValue(slot,value as *mut c_void)},0);let current=unsafe{FlsGetValue(slot)}as usize;assert_eq!(current,value);tx.send((value,unsafe{GetCurrentThreadId()})).unwrap();stop_rx.recv().unwrap();}));ids.push(rx.recv().unwrap());stops.push(stop_tx);}
 if early{for tx in stops{tx.send(()).unwrap();}for h in workers{h.join().unwrap();}let before=EVENTS.lock().unwrap().clone();assert_eq!(before.len(),2);assert_ne!(unsafe{FlsFree(slot)},0);assert_eq!(EVENTS.lock().unwrap().len(),2);for(v,t)in &before{assert_eq!(*t,ids.iter().find(|(value,_)|value==v).unwrap().1);}println!("case=thread_exit width={} callbacks={before:?} owner={owner} workers={ids:?}",std::mem::size_of::<usize>()*8);}
 else{assert_ne!(unsafe{FlsFree(slot)},0);let during=EVENTS.lock().unwrap().clone();for tx in stops{tx.send(()).unwrap();}for h in workers{h.join().unwrap();}let all=EVENTS.lock().unwrap().clone();assert_eq!(during.len(),2);assert_eq!(all.len(),2);for(v,t)in &all{assert!(ids.iter().any(|(value,_)|value==v));assert_eq!(*t,owner);}println!("case=owner_free_live_workers width={} callbacks={all:?} owner={owner} workers={ids:?}",std::mem::size_of::<usize>()*8);}
 }println!("PASS shared slot isolated values,2 worker exit callbacks and2 synchronous owner free callbacks");}
''';probe=out/'probe.rs';probe.write_text(code,encoding='utf-8');results=[];files=[probe]
